-- Scale of the values of a DECIMAL CASE whose results have a smaller scale, read directly,
-- as strings, as numbers, through a temporary table, a derived table, a subquery; IF,
-- IFNULL, COALESCE, GREATEST, UNION alike. The values of CREATE TABLE ... AS SELECT have
-- the scale of the column: these statements read the values directly.
DROP TABLE IF EXISTS cs;
CREATE TABLE cs (k INT NOT NULL, i INT NOT NULL, n DECIMAL(10, 2) NOT NULL, m DECIMAL(10, 1) NOT NULL, b BIGINT UNSIGNED NOT NULL);
INSERT INTO cs VALUES (1, 42, 12.50, 3.5, 7), (0, 42, 12.50, 3.5, 7);
SELECT k, CASE WHEN k > 0 THEN i ELSE n END AS c_i_n, CASE WHEN k > 0 THEN m ELSE n END AS c_m_n, CASE WHEN k > 0 THEN 5 ELSE 1.50 END AS c_lit, CASE WHEN k > 0 THEN 1.5 ELSE 2.25 END AS c_lit_dec, CASE WHEN k > 0 THEN b ELSE n END AS c_b_n FROM cs ORDER BY k;
SELECT k, CONCAT(CASE WHEN k > 0 THEN i ELSE n END) AS s_i_n, CONCAT(CASE WHEN k > 0 THEN m ELSE n END) AS s_m_n, CONCAT(CASE WHEN k > 0 THEN 1.5 ELSE 2.25 END) AS s_lit_dec, CASE WHEN k > 0 THEN i ELSE n END + 0 AS p_i_n FROM cs ORDER BY k;
SELECT k, IF(k > 0, i, n) AS if_i_n, IF(k > 0, m, n) AS if_m_n, IFNULL(i, n) AS ifnull_i_n, COALESCE(i, n) AS coalesce_i_n, COALESCE(m, n) AS coalesce_m_n, GREATEST(i, n) AS greatest_i_n, NULLIF(i, n) AS nullif_i FROM cs ORDER BY k;
SELECT k, CONCAT(IF(k > 0, i, n)) AS if_i_n, CONCAT(COALESCE(i, n)) AS coalesce_i_n, CONCAT(COALESCE(m, n)) AS coalesce_m_n FROM cs ORDER BY k;
SELECT u FROM (SELECT i AS u FROM cs WHERE k = 1 UNION ALL SELECT n FROM cs WHERE k = 1) AS q;
SELECT CONCAT(u) AS u FROM (SELECT i AS u FROM cs WHERE k = 1 UNION ALL SELECT n FROM cs WHERE k = 1) AS q;
SELECT k, CASE WHEN k > 0 THEN i ELSE n END AS v FROM cs ORDER BY v;
SELECT MAX(CASE WHEN k > 0 THEN i ELSE n END) AS mx, MIN(CASE WHEN k > 0 THEN i ELSE n END) AS mn FROM cs;
SELECT k, CASE WHEN k > 0 THEN i ELSE n END LIKE '42' AS lk, CASE WHEN k > 0 THEN i ELSE n END = '42' AS eq_s, CASE WHEN k > 0 THEN i ELSE n END IN (42, 1) AS inl, CASE WHEN k > 0 THEN i ELSE n END BETWEEN 42 AND 42 AS btw FROM cs ORDER BY k;
SELECT CASE WHEN k > 0 THEN i ELSE n END AS v, COUNT(*) AS c FROM cs GROUP BY v ORDER BY v;
SELECT CASE WHEN k > 0 THEN i ELSE n END AS v, COUNT(*) AS c FROM cs GROUP BY CASE WHEN k > 0 THEN i ELSE n END;
SELECT k, CASE WHEN k >= 0 THEN CASE WHEN k > 0 THEN i ELSE n END ELSE 'x' END AS str_outer, CASE WHEN k >= 0 THEN CASE WHEN k > 0 THEN i ELSE n END ELSE 1.555 END AS dec_outer, CASE WHEN k >= 0 THEN CASE WHEN k > 0 THEN i ELSE n END ELSE 1e0 END AS dbl_outer FROM cs ORDER BY k;
SELECT k, v FROM (SELECT k, CASE WHEN k > 0 THEN i ELSE n END AS v FROM cs) AS q ORDER BY k;
SELECT k, v FROM (SELECT k, CASE WHEN k > 0 THEN i ELSE n END AS v FROM cs LIMIT 5) AS q ORDER BY k;
SELECT k, CONCAT(v) AS v FROM (SELECT k, CASE WHEN k > 0 THEN i ELSE n END AS v FROM cs) AS q ORDER BY k;
SELECT DISTINCT CASE WHEN k > 0 THEN i ELSE n END AS v FROM cs ORDER BY v;
SELECT CASE WHEN k > 0 THEN i ELSE n END AS v FROM cs UNION ALL SELECT 1 ORDER BY 1;
SELECT k, CASE WHEN k > 0 THEN -i ELSE n END AS neg_branch, -CASE WHEN k > 0 THEN i ELSE n END AS neg FROM cs ORDER BY k;
SELECT k, LENGTH(CASE WHEN k > 0 THEN i ELSE n END) AS len, ABS(CASE WHEN k > 0 THEN i ELSE n END) AS ab, ROUND(CASE WHEN k > 0 THEN i ELSE n END, 1) AS rd, UPPER(CASE WHEN k > 0 THEN i ELSE n END) AS up FROM cs ORDER BY k;
SELECT GROUP_CONCAT(CASE WHEN k > 0 THEN i ELSE n END ORDER BY k) AS gc, SUM(CASE WHEN k > 0 THEN i ELSE n END) AS sm, AVG(CASE WHEN k > 0 THEN i ELSE n END) AS av, MIN(CASE WHEN k > 0 THEN i ELSE n END) AS mn FROM cs;
SELECT k, FIRST_VALUE(CASE WHEN k > 0 THEN i ELSE n END) OVER (ORDER BY k DESC) AS fv, LAG(CASE WHEN k > 0 THEN i ELSE n END) OVER (ORDER BY k DESC) AS lg FROM cs ORDER BY k;
SELECT k, (SELECT CASE WHEN k > 0 THEN i ELSE n END) AS sub FROM cs ORDER BY k;
DROP TABLE cs;
